def can_remove_left(a):
    n = len(a)
    s = 0
    for i in range(n - 1):
        if s > a[i]:
            return False
        s -= a[i]
    return s == 0

def solution(data):
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()[1:]))
        clauses.append(parts[1:])

    # Build an implication graph where vertices are literals
    # For each clause (x1 OR x2 OR ... OR xk OR ...), if we know xi is false,
    # then at least one other literal must be true
    # Since each variable appears at most 2 times, this is related to 2-SAT

    # Track which clauses contain each variable
    var_in_clauses = {}
    for i, clause in enumerate(clauses):
        for lit in clause:
            var_in_clauses.setdefault(abs(lit), []).append((i, lit))

    # Assign variable values
    assignment = [None] * (m + 1)
    sat = [False] * n

    # Process clauses to determine forced assignments
    for i, clause in enumerate(clauses):
        if sat[i]:
            continue
        # Calculate how many literals are false
        false_count = 0
        l = 1
        sat[i] = True
        # Try setting each literal to false in sequence
        for j, lit in enumerate(clause):
            if sat[i]:
                break
            assignment[lit] = 1
            l += 1

    # Check for consistency
    for i in range(1, m + 1):
        if assignment[i] != 1:
            for j, lit in var_in_clauses.get(i, []):
                if assignment[lit] == 0:
                    return 'NO\n' + ''.join(['1' if assignment[k] if assignment[k] is not None else '0' for k in range(1, m + 1)])

    # Still need to check clause satisfaction
    for i, clause in enumerate(clauses):
        if not sat[i]:
            return 'NO\n' + ''.join(['1' if assignment[k] if assignment[k] is not None else '0' for k in range(1, m + 1)])

    # Return assignment with "YES"
    result = ''.join(['1' if assignment[k] == 1 else '0' for k in range(1, m + 1)])
    return 'YES\n' + result

