import sys
from typing import List, Tuple, Dict

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    # Store edges with original index
    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((e, a, b, i))

    # If m == n-1, all edges are in MST, output nothing
    if m == n - 1:
        return ''

    # Sort edges by weight for Kruskal's
    sorted_edges = sorted(edges, key=lambda x: x[0])

    # Union-Find data structure
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(i: int) -> int:
        root = i
        while parent[root] != root:
            root = parent[root]

        # Path compression
        curr = i
        while curr != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    def union(i: int, j: int) -> bool:
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True
        return False

    # Build MST adjacency list
    adj = [[] for _ in range(n + 1)]
    mst_mask = [False] * m

    for e, a, b, idx in sorted_edges:
        mst_mask[idx] = union(a, b)
        if mst_mask[idx]:
            adj[a].append((b, e))
            adj[b].append((a, e))

    # Prepare for LCA and max edge on path
    LOG = (n).bit_length() + 2

    # DFS to compute depth and binary lifting tables
    depth = [0] * (n + 1)
    parent_table = [[0] * LOG for _ in range(n + 1)]
    max_edge_table = [[0] * LOG for _ in range(n + 1)]

    # Stack-based DFS to avoid recursion depth issues
    stack = [(1, -1, -1)]  # (node, parent, max_edge_from_parent)

    while stack:
        u, par, max_e = stack.pop()
        depth[u] = depth[par] + 1 if par != -1 else 0
        parent_table[u][0] = par
        max_edge_table[u][0] = max_e

        for v, w in adj[u]:
            if v != par:
                stack.append((v, u, w))

    # Build binary lifting tables in reverse order of levels
    for j in range(1, LOG):
        for i in range(1, n + 1):
            p = parent_table[i][j - 1]
            parent_table[i][j] = parent_table[p][j - 1] if p != 0 else 0
            if p == 0:
                max_edge_table[i][j] = max_edge_table[i][j - 1]
            else:
                max_edge_table[i][j] = max(max_edge_table[i][j - 1], max_edge_table[p][j - 1])

    def query_max(u: int, v: int) -> int:
        # Lift deeper node to same depth
        if depth[u] < depth[v]:
            u, v = v, u

        max_w = 0
        diff = depth[u] - depth[v]

        for j in range(LOG):
            if (diff >> j) & 1:
                max_w = max(max_w, max_edge_table[u][j])
                u = parent_table[u][j]

        if u == v:
            return max_w

        # Lift both until just below LCA
        for j in range(LOG - 1, -1, -1):
            if parent_table[u][j] != parent_table[v][j]:
                u = parent_table[u][j]
                v = parent_table[v][j]
                max_w = max(max_w, max(max_edge_table[u][0], max_edge_table[v][0]))

        return max(max_w, max(max_edge_table[u][0], max_edge_table[v][0]))

    # For each non-MST edge in input order, compute max weight on path
    results = []
    for e, a, b, idx in sorted_edges:
        if not mst_mask[idx]:
            results.append(query_max(a, b))

    # Output in order of non-MST edges in input
    output_lines = []
    for e, a, b, idx in edges:
        if not mst_mask[idx]:
            output_lines.append(str(query_max(a, b)))

    return '\n'.join(output_lines)


def solution2(input_str: str) -> str:
    """Alternative implementation with cleaner code structure"""
    lines = input_str.strip().split('\n')
    if not lines:
