    n, m = map(int, lines[0].split())

    # Parse edges with original index
    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, e, i))

    # If no non-MST edges, return empty
    if m == n - 1:
        return ''

    # Sort by weight for MST construction
    sorted_indices = sorted(range(m), key=lambda x: edges[x][2])

    # Union-Find
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def get(root):
        if parent[root] == root:
            return root
        return parent[root] = get(parent[root])

    def unite(x, y):
        rx, ry = get(x), get(y)
        if rx != ry:
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            if rank[rx] == rank[ry]:
                rank[rx] += 1
            return True
        return False

    # Identify MST edges using original indices
    in_mst = [False] * m
    mst_adj = [[] for _ in range(n + 1)]
    mst_nodes = set()

    for idx in sorted_indices:
        a, b, e, _ = edges[idx]
        in_mst[idx] = unite(a, b)
        if in_mst[idx]:
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_nodes.add(a)
            mst_nodes.add(b)

    # Binary lifting for LCA and max edge
    LOG = 19  # Sufficient for n <= 10^5
    depth = [0] * (n + 1)
    up = [[0] * LOG for _ in range(n + 1)]
    mx = [[0] * LOG for _ in range(n + 1)]

    # DFS using stack
    stack = [(1, 0, 0)]
    visited = [False] * (n + 1)
    visited[1] = True
    depth[1] = 0

    while stack:
        u, p, mw = stack.pop()
        if p != 0:
            visited[u] = True  # Ensure processed
        depth[u] = depth[p] + 1
        up[u][0] = p
        mx[u][0] = mw

        for v, w in mst_adj[u]:
            if v != p:
                stack.append((v, u, w))

    # Build tables
    for j in range(1, LOG):
        for i in range(1, n + 1):
            p = up[i][j - 1]
            up[i][j] = up[p][j - 1]
            mx[i][j] = max(mx[i][j - 1], mx[p][j - 1])

    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        diff = depth[u] - depth[v]
        max_e = 0
        for j in range(LOG):
            if (diff >> j) & 1:
                max_e = max(max_e, mx[u][j])
                u = up[u][j]

        if u == v:
            return max_e

        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]

        return max(max(mx[u][0], mx[v][0]), max_e)

    # Collect results
    results = []
    for idx in range(m):
        if not in_mst[idx]:
            a, b, e, _ = edges[idx]
            results.append(str(query_max(a, b)))

    return '\n'.join(results)


