import sys
from collections import deque

def check_input_parse(s):
    # Split by spaces and newlines to get all integers
    tokens = [t for t in s.replace('\n', ' ').split() if t.isdigit()]
    if len(tokens) != 6:
        return None
    return map(int, tokens)

def can_reach(board_size, chip_pos, target_pos):
    """Check if chip can reach target position (ignoring glue)"""
    n, m = board_size
    x1, y1 = chip_pos
    x2, y2 = target_pos

    # BFS to check reachability
    visited = {}
    visited[(x1, y1)] = 0
    queue = deque([((x1, y1), 0)])

    while queue:
        (cx, cy), dist = queue.popleft()
        if (cx, cy) == (x2, y2):
            return True

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = cx - dx, cy - dy  # Adjust: dx,dy are movement direction

            # Fix: check all 4 directions correctly
            for nx_change, ny_change in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                na, nb = cx + nx_change, cy + ny_change
                if 1 <= na <= n and 1 <= nb <= m:
                    if (na, nb) not in visited:
                        visited[(na, nb)] = dist + 1
                        queue.append(((na, nb), dist + 1))

    return (x1, y1) == (x2, y2)  # Already at target

def can_move_to(board_size, pos):
    n, m = board_size
    x, y = pos
    return 1 <= x <= n and 1 <= y <= m

def has_valid_move(board_size, x, y, glue_mask):
    n, m = board_size
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nx, ny = x + dx, y + dy
        if 1 <= nx <= n and 1 <= ny <= m:
            neighbor = (nx, ny)
            if not (glue_mask & (1 << (nx * m + ny))):
                return neighbor
    return None

def solve_game_recursion(n, m, x1, y1, x2, y2):
    """
    Recursive backtracking with memoization to determine winner.
    Key insight: This is a finite deterministic zero-sum game.
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def can_first_win(chips, glue_set, depth_limit):
        """Check if first player can win from this state."""
        state = (tuple(chips[0]), tuple(chips[1]), tuple(glue_set))

        # Check if first player already won (chips at same position)
        if chips[0] == chips[1]:
            return True

        # If depth limit reached, simulate optimal play
        if depth_limit == 0:
            return False

        # Chips to move
        possible_moves = []
        for chip_idx in range(2):
            cx, cy = chips[chip_idx]
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 1 <= nx <= n and 1 <= ny <= m:
                    neighbor = make_cell_possible(glue_set, nx, ny)
                    if neighbor is not None:
                        possible_moves.append((chip_idx, nx, ny))

        if not possible_moves:
            # No moves possible, second player wins
            return False

        # First player chooses the best move
        for chip_idx, nx, ny in possible_moves:
            # Try this move for first player
            new_chip = list(chips)
            new_chip[chip_idx] = (nx, ny)

            # Second player will try to prevent winning
            for cover_x, cover_y in possible_glue_positions(n, m, new_chip, glue_set):
                # Second player covers this square with glue
                new_glue = set(glue_set)
                new_glue.add((cover_x, cover_y))

                # Check if first player still can win from this state
                if not can_first_win(tuple(new_chip), new_glue, depth_limit - 1):
                    return True

        return False

    return can_first_win((x1, y1), (x2, y2), set())

def make_cell_possible(glue_set, nx, ny):
    """Check if square (nx, ny) is not already glued."""
    if (nx, ny) in glue_set:
        return False
    return True

def possible_glue_positions(n, m, chips, glue_set):
    """Get all possible positions second player can glue."""
    positions = []
    for x in range(1, n + 1):
        for y in range(1, m + 1):
            if (x, y) not in glue_set and (x, y) != chips[0] and (x, y) != chips[1]:
                positions.append((x, y))
    return positions

