MOD_EXP = 10**9 + 6

def mat_mul(A, B, P):
    C = [[0]*5 for _ in range(5)]
    for i in range(5):
        for k in range(5):
            if A[i][k] == 0:
                continue
            for j in range(5):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % P
    return C

def mat_pow(A, P, Q):
    result = [[0]*5 for _ in range(5)]
    for i in range(5):
        result[i][i] = 1
    base = A
    while P:
        if P & 1:
            result = mat_mul(result, base, Q)
        base = mat_mul(base, base, Q)
        P >>= 1
    return result

