def solution(input_data):
    if not input_data.strip():
        return '0\n'

    lines = [line.strip() for line in input_data.strip().split('\n') if line.strip()]
    if not lines:
        return '0\n'

    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transforms = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        if len(parts) >= 5:
            x0, y0, d0, t0, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            transforms.append((x0, y0, d0, t0, e))

    # cell_cost[r][c] stores the energy cost to kill transformers at (r,c) at time r+c
    cell_cost = [[0] * M for _ in range(N)]

    for r in range(N):
        for c in range(M):
            time = r + c
            for x0, y0, d0, t0, e in transforms:
                if time < t0:
                    continue
                phase = (time - t0) % 4

                if phase == 0:
                    if x0 == r and y0 == c:
                        cell_cost[r][c] += e
                elif phase == 1:
                    if x0 + d0 == r and y0 - d0 == c:
                        cell_cost[r][c] += e
                elif phase == 2:
                    if x0 + d0 == r and y0 == c:
                        cell_cost[r][c] += e
                elif phase == 3:
                    if x0 == r and y0 + d0 == c:
                        cell_cost[r][c] += e

    # DP for minimum energy path
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = cell_cost[0][0]

    for r in range(N):
        for c in range(M):
            if dp[r][c] == float('inf'):
                continue

            if r + 1 < N:
                dp[r + 1][c] = min(dp[r + 1][c], dp[r][c] + cell_cost[r + 1][c])
            if c + 1 < M:
                dp[r][c + 1] = min(dp[r][c + 1], dp[r][c] + cell_cost[r][c + 1])

    return f"{dp[N - 1][M - 1]}\n"

