import sys

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.data = data
        self.tree = [None] * (4 * self.n)
        self.build(1, 0, self.n - 1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = [self.data[start], self.data[start]]
        else:
            mid = (start + end) // 2
            self.build(2 * node, start, mid)
            self.build(2 * node + 1, mid + 1, end)
            self.tree[node] = self.merge(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, node, start, end, l, r):
        if r < start or end < l:
            return None
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        left = self.query(2 * node, start, mid, l, r)
        right = self.query(2 * node + 1, mid + 1, end, l, r)
        if left is None:
            return right
        if right is None:
            return left
        return self.merge(left, right)

    def merge(self, left, right):
        max_v = max(left[0], right[0])
        min_v = min(left[1], right[1])
        cross = max(left[0], right[0]) + max(min(left[1], right[1]), min(left[1], right[1]))
        return [max(left[0], right[0] + left[0], left[0] + right[0]), min(left[1], right[1])]

    def query(self, l, r):
        return self.query(1, 0, self.n - 1, l, r)

