        a, b, c, d = map(int, parts)
        points.append((a, b, c, d))

    def normalize(coords):
        """Returns canonical direction identifier (all negatives flipped)"""
        if all(c == 0 for c in coords):
            return tuple(coords)

        g = abs(coords[0])
        for c in coords[1:]:
            g = gcd(g, abs(c))

        result = tuple(c // g for c in coords)

        # Make sure first nonzero component is positive
        for c in result:
            if c != 0:
                if c < 0:
                    result = tuple(-x for x in result)
                break

        return tuple(result)

    # Group points by their direction from origin
    direction_groups = defaultdict(list)
    for coords in points:
        direction = normalize(coords)
        direction_groups[direction].append(coords)

    # Count valid sets: for m collinear points, C(m,4) valid combinations
    # Each valid combination of 4 collinear points from same direction 
    # can form exactly one k=2 pair set meeting the condition
    answer = 0
    for direction, coords_list in direction_groups.items():
        m = len(coords_list)
        if m >= 4:
            # C(m, 4) = m! / (4! * (m-4)!) = m*(m-1)*(m-2)*(m-3)/24
            combinations = m * (m - 1) * (m - 2) * (m - 3) // 24
            answer = (answer + combinations) % MOD

    return f"{answer}\n"

