    # Base case: f(0, n) = 2^(number of distinct prime factors of n)
    for i in range(1, max_n + 1):
        fr[0][i] = (1 << num_distinct_prime_factors[i]) % MOD

    # Compute higher r values using divisor sum property
    # For r >= 1: fr[n] = sum_{d|n} f(r-1, d)
    # This is computed efficiently by iterating over all divisors d and adding
    # fr[r-1][d] to all multiples of d

    for r in range(1, max_r + 1):
        for d in range(1, max_n + 1):
            val = fr[r-1][d]
            if val == 0:
                continue
            for multiple in range(d, max_n + 1, d):
                fr[r][multiple] += val
                if fr[r][multiple] >= MOD:
                    fr[r][multiple] -= MOD

    # Answer queries
    results = []
    for r, n in queries:
        result = fr[r][n]
        results.append(str(result))

    return '\n'.join(results)


