def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    best_seq = None
    best_cost = float('inf')

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def is_coprime_with_all(picked, val):
        for x in picked:
            if gcd(x, val) != 1:
                return False
        return True

    def backtrack(idx, picked, cost):
        nonlocal best_seq, best_cost

        # Pruning: if current cost already exceeds best, stop exploring this branch
        if cost >= best_cost:
            return

        if idx == n:
            if cost < best_cost:
                best_cost = cost
                best_seq = list(picked)
            return

        # Try values from 1 to 30
        for val in range(1, 31):
            if is_coprime_with_all(picked, val):
                picked.append(val)
                backtrack(idx + 1, picked, cost + abs(a[idx] - val))
                picked.pop()

    backtrack(0, [], 0)
    return ' '.join(map(str, best_seq))

