def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])
    test_cases = []
    for i in range(1, t + 1):
        if i < len(lines):
            line = lines[i].strip()
            if line:
                test_cases.append(int(line))

    if not test_cases:
        return ''

    max_n = max(test_cases)

    # Generate Fibonacci numbers: F1=1, F2=2, Fi=Fi-1+Fi-2
    fibs = []
    a, b = 1, 2
    while a <= max_n:
        fibs.append(a)
        a, b = b, a + b

    # Memoization cache
    seen = {}

    def count_decompositions(target_sum, max_idx):
        """Count ways to decompose target_sum using Fibonacci numbers up to index max_idx"""
        if target_sum == 0:
            return 1  # One way: empty decomposition (all covered by our choices)
        if max_idx < 0:
            return 0  # No Fibonacci numbers available

        key = (target_sum, max_idx)
        if key in seen:
            return seen[key]

        # If current Fibonacci is too large, skip it
        if fibs[max_idx] > target_sum:
            seen[key] = count_decompositions(target_sum, max_idx - 1)
            return seen[key]

        # Option 1: Don't use fibs[max_idx]
        # Option 2: Use fibs[max_idx] and recurse with max_idx - 2 (can't use consecutive)
        result = (count_decompositions(target_sum, max_idx - 1) + 
                  count_decompositions(target_sum - fibs[max_idx], max_idx - 2))
        seen[key] = result
        return result

    results = []
    for n in test_cases:
        # Find the largest Fibonacci number <= n
        max_idx = 0
        for i, f in enumerate(fibs):
            if f <= n:
                max_idx = i

        ans = count_decompositions(n, max_idx)
        results.append(str(ans))

    return '\n'.join(results)

from itertools import combinations

def solution(input_str):
    """
    Counts valid binary code variants that match all system responses.

    Args:
        input_str: String containing n, m and m attempts with responses

    Returns:
        String with the count of valid code variants
    """
    input_str = input_str.strip()
    if not input_str:
        return "0"

    lines = input_str.split('\n')
    if len(lines) < 1:
        return "0"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "0"

    # Parse all attempts
    attempts = []
    for i in range(1, m + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                s = parts[0]
                c = int(parts[1])
                attempts.append((s, c))

    # If no attempts, 2^n possible codes
    if m == 0:
        return str(2**n)

    # Handle edge case
    if len(attempts) == 0:
        return "0"

    # Get first attempt's binary string and matching count
    s0, c0 = attempts[0]
    s0_ints = [int(c) for c in s0]

    # Counter of valid codes
    ans = 0

    # Try all ways to choose c0 positions that match the first attempt
    for match_indices in combinations(range(n), c0):
        # Build candidate code:
        # - Positions in match_indices match s0
        # - Other positions DON'T match s0 (so have opposite value)
        candidate = [None] * n

        # Set matching positions
        match_set = set(match_indices)
        for pos in match_set:
            candidate[pos] = s0_ints[pos]

        # Set non-matching positions
        for pos in range(n):
            if candidate[pos] is None:
                candidate[pos] = 1 - s0_ints[pos]

        # Convert to string for checking
        candidate_s = ''.join(str(x) for x in candidate)

        # Verify this candidate against ALL attempts
        valid = True
        for s_str, c_target in attempts:
            matches = 0
            for i in range(n):
                if candidate_s[i] == s_str[i]:
                    matches += 1

            if matches != c_target:
                valid = False
                break

        if valid:
            ans += 1

    return str(ans)
